import json,uuid,pathlib
nodes=[];connections={}
def node(name,type,version,position,parameters):
 n={'id':str(uuid.uuid5(uuid.NAMESPACE_URL,'https://ai.th.io.vn/n8n/'+name)),'name':name,'type':type,'typeVersion':version,'position':position,'parameters':parameters};nodes.append(n);return n
def connect(source,target,kind='ai_tool'):
 connections.setdefault(source,{})[kind]=[[{'node':target,'type':kind,'index':0}]]
node('When chat message received','@n8n/n8n-nodes-langchain.chatTrigger',1.3,[0,0],{'public':False,'options':{'responseMode':'lastNode'}})
node('AI Agent','@n8n/n8n-nodes-langchain.agent',3.1,[300,0],{'promptType':'auto','options':{'systemMessage':'Bạn là trợ lý điều phối của TH AI.Agent. Trả lời bằng ngôn ngữ người dùng. Giao nghiên cứu cho Research Agent và thao tác bảng tính cho Sheet Agent. Chỉ ghi Google Sheets khi người dùng yêu cầu rõ ràng. Không tự gửi email, đăng bài hoặc kích hoạt workflow. Không khẳng định đã dùng công cụ nếu chưa có kết quả. Hỏi lại khi thiếu bảng tính hoặc trường dữ liệu.','maxIterations':5}})
connect('When chat message received','AI Agent','main')
for i,(name,target,x,y) in enumerate([('Google Gemini Chat Model','AI Agent',170,230),('Google Gemini Research Model','Research Agent',130,640),('Google Gemini Sheet Model','Sheet Agent',730,640)]):
 node(name,'@n8n/n8n-nodes-langchain.lmChatGoogleGemini',1.2,[x,y],{'options':{'temperature':0.2}});connect(name,target,'ai_languageModel')
for name,target,prefix,x,y in [('Conversation Memory','AI Agent','main',370,230),('Research Memory','Research Agent','research',330,640),('Sheet Memory','Sheet Agent','sheet',930,640)]:
 node(name,'@n8n/n8n-nodes-langchain.memoryPostgresChat',1.3,[x,y],{'sessionIdType':'customKey','sessionKey':"={{ '"+prefix+":' + $('When chat message received').first().json.sessionId }}",'tableName':'th_agent_chat_memory','contextWindowLength':5});connect(name,target,'ai_memory')
node('Think','@n8n/n8n-nodes-langchain.toolThink',1.1,[1000,200],{'description':'Use this tool to organize a short plan before choosing tools. It does not fetch information or write data.'});connect('Think','AI Agent')
node('Research Agent','@n8n/n8n-nodes-langchain.agentTool',3,[300,400],{'toolDescription':'Research a topic using Perplexity, verify sources, and return a concise answer with URLs. This tool never writes to Sheets.','text':"={{ $fromAI('research_request', 'Research question and requirements', 'string') }}",'options':{'systemMessage':'Bạn là Research Agent. Dùng Perplexity cho dữ liệu mới. Nêu nguồn và phân biệt thông tin đã xác minh với giả định. Không tự thực hiện thao tác ghi dữ liệu.','maxIterations':3}});connect('Research Agent','AI Agent')
node('Sheet Agent','@n8n/n8n-nodes-langchain.agentTool',3,[900,400],{'toolDescription':'Append the data explicitly requested by the user to the configured Google Sheet. Ask for missing fields. Never append speculative results or write without a user request.','text':"={{ $fromAI('sheet_request', 'Explicitly requested rows to append, including task, result and source', 'string') }}",'options':{'systemMessage':'Bạn là Sheet Agent. Chỉ dùng Append khi người dùng đã yêu cầu ghi dữ liệu rõ ràng. Hãy kiểm tra Task, Result, Source; không bịa nguồn. Trả lại kết quả công cụ để người dùng biết đã ghi hay chưa.','maxIterations':3}});connect('Sheet Agent','AI Agent')
node('Perplexity','n8n-nodes-base.httpRequestTool',4.3,[540,640],{'toolDescription':'Search and synthesize current information with Perplexity Sonar. Return the answer and citations.','method':'POST','url':'https://api.perplexity.ai/chat/completions','authentication':'genericCredentialType','genericAuthType':'httpHeaderAuth','sendBody':True,'specifyBody':'json','jsonBody':"={{ { model: 'sonar', messages: [{ role: 'user', content: $fromAI('query', 'Research question to send to Perplexity', 'string') }] } }}",'options':{'timeout':60000}});connect('Perplexity','Research Agent')
node('Append','n8n-nodes-base.googleSheetsTool',4.7,[1150,640],{'operation':'append','documentId':{'__rl':True,'value':'','mode':'id'},'sheetName':{'__rl':True,'value':'','mode':'name'},'columns':{'mappingMode':'defineBelow','value':{'Task':"={{ $fromAI('Task', 'Task or subject explicitly requested by the user', 'string') }}",'Result':"={{ $fromAI('Result', 'Verified result to save', 'string') }}",'Source':"={{ $fromAI('Source', 'Source URL or a blank string if not applicable', 'string') }}"},'matchingColumns':[],'schema':[]},'options':{}});connect('Append','Sheet Agent')
node('Start here','n8n-nodes-base.stickyNote',1,[-80,-340],{'width':1360,'height':220,'color':5,'content':'## TH AI.Agent · Multi-agent workspace\n1. Connect your Google Gemini credential to all three model nodes and choose an available current model.\n2. Memory is connected automatically to private PostgreSQL and survives restarts.\n3. Perplexity: create Header Auth with Name `Authorization`, Value `Bearer YOUR_KEY`.\n4. Append: connect Google Sheets OAuth, choose spreadsheet + sheet with columns Task, Result, Source.\n5. Open chat to test. Keep Inactive until credentials are configured. No AI request or Sheet write is performed by installation.'})
workflow={'id':'THAIMultiAgent01','name':'TH AI.Agent · Research & Sheets','active':False,'nodes':nodes,'connections':connections,'settings':{'executionOrder':'v1','saveDataErrorExecution':'all','saveDataSuccessExecution':'all','executionTimeout':180},'pinData':{},'tags':[]}
pathlib.Path(__file__).with_name('workflow.json').write_text(json.dumps(workflow,ensure_ascii=False,indent=2)+'\n')
